        if x <= N:
            counts[x] += 1
    return counts

def find_good_sequences_N4():
    import itertools
    solutions = []
    for a in itertools.product(range(6), repeat=5):
        if sum(a) == 5:
            b = get_f(a, 4)
            if get_f(b, 4) == a:
                solutions.append(a)
    return solutions

